import sys

def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    lengths = list(map(int, input[1:]))

    if N == 1:
        print("YES")
        print("0")
        return

    words = []
    used = set()

    def backtrack(current_word, length):
        if length == 0:
            binary_word = ''.join(map(str, current_word))
            if all(binary_word[:i] not in used for i in range(1, len(binary_word))):
                used.add(binary_word)
                words.append(binary_word)
                return True
            return False

        for bit in [0, 1]:
            current_word.append(bit)
            if backtrack(current_word, length - 1):
                return True
            current_word.pop()
        return False

    for length in sorted(lengths, reverse=True):
        if not backtrack([], length):
            print("NO")
            return

    print("YES")
    for word in words:
        print(word)

if __name__ == "__main__":
    main()
